gdEE(){return"\u2139\ufe0f \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u0628\u0627 \u062d\u0627\u0644\u062a \xab\u0627\u06cc\u062c\u0627\u062f \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062c\u062f\u06cc\u062f\xbb \u06cc\u06a9 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062c\u062f\u06cc\u062f \u0628\u0627 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u0641\u0627\u06cc\u0644 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u0627\u06cc\u062c\u0627\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0641\u0639\u0644\u06cc \u0634\u0645\u0627 \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f."},
