gdGZ(){return"\u0634\u0646\u0627\u0633\u0647 \u0645\u0644\u06cc \u0628\u0627\u06cc\u062f \u06f1\u06f1 \u0631\u0642\u0645 \u0628\u0627\u0634\u062f"},
