gdFt(){return"\u067e\u0633 \u0627\u0632 \u062a\u0648\u0644\u06cc\u062f\u060c CSR \u0631\u0627 \u062f\u0631 \u0645\u0631\u06a9\u0632 \u0635\u062f\u0648\u0631 \u06af\u0648\u0627\u0647\u06cc \u062b\u0628\u062a \u06a9\u0646\u06cc\u062f \u0648 \u0641\u0627\u06cc\u0644 \u06af\u0648\u0627\u0647\u06cc \u0631\u0627 \u062f\u0631 \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u0646\u0645\u0627\u06cc\u06cc\u062f."},
