gbTZ(){return"\u0627\u0642\u0644\u0627\u0645 \u0641\u0627\u0642\u062f \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc \u0631\u0627 \u067e\u06cc\u0634 \u0627\u0632 \u0627\u0631\u0633\u0627\u0644 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0646\u06cc\u062f."},
