gcWJ(){return"\u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u067e\u0644\u0646 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0628\u0628\u0646\u062f\u06cc\u062f\u061b \u0627\u06af\u0631 \u0631\u0648\u0634\u0646 \u0628\u0645\u0627\u0646\u062f\u060c \u0645\u062b\u0644 \u0633\u0627\u06cc\u0631 \u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u0633\u062a."},
gcWI(){return"\u0627\u0644\u0627\u0646 \u062f\u0631 \u0633\u0637\u062d \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a. \u0627\u0632 \u0645\u0633\u06cc\u0631 \xab\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u2192 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM\xbb (\u06cc\u0627 \u0645\u0646\u0648\u06cc \u0645\u0631\u0628\u0648\u0637) \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0631\u0633\u0627\u0644 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0686\u062a \u0648\u0628 \u0631\u0627 \u0631\u0648\u0634\u0646 \u06a9\u0646\u06cc\u062f\u060c \u0628\u0639\u062f \u0628\u0631\u06af\u0631\u062f\u06cc\u062f \u0648 \u0627\u06cc\u0646 \u0633\u0648\u06cc\u06cc\u0686 \u0631\u0627 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u0646\u06cc\u062f."},
gcWQ(){return"\u0648\u06cc\u062c\u062a \u0641\u0639\u0627\u0644"},
