gcWj(){return"\u0644\u0637\u0641\u0627\u064b \xab\u0646\u0627\u0645 \u0648\u06cc\u062c\u062a\xbb \u0631\u0627 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f (\u0645\u062b\u0644\u0627\u064b \u0646\u0627\u0645 \u0633\u0627\u06cc\u062a \u06cc\u0627 \u0628\u062e\u0634)."},
