gcWi(){return"\u0636\u0628\u0637 \u0635\u062f\u0627 \u062f\u0631 \u0645\u0631\u0648\u0631\u06af\u0631 \u0627\u06cc\u0646 \u0646\u0633\u062e\u0647 \u062f\u0631 \u062f\u0633\u062a \u0646\u06cc\u0633\u062a\u061b \u0627\u0632 \u0627\u067e \u06cc\u0627 \u062f\u06a9\u0645\u0647\u0654 \u067e\u06cc\u0648\u0633\u062a \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f"},
