gcKi(){return"\u0635\u0641\u062d\u0647\u0654 \u0648\u0627\u062d\u062f"},
gcKj(){return"\u062f\u0631 \u0647\u0631 \u0632\u0645\u0627\u0646 \u0641\u0642\u0637 \u06cc\u06a9 \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0627\u0633\u062a (\u0646\u0627\u0648\u0628\u0631\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9)"},
gcKk(){return"\u062a\u0628 \u062f\u0631 \u0646\u0648\u0627\u0631 \u0628\u0627\u0644\u0627"},
