gcKh(){return"\u062d\u0627\u0644\u062a \u062a\u0628 \u0641\u0642\u0637 \u062f\u0631 \u0639\u0631\u0636 \u0632\u06cc\u0627\u062f \u0627\u0639\u0645\u0627\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u0645\u0648\u0628\u0627\u06cc\u0644 \u0647\u0645\u06cc\u0634\u0647 \u062d\u0627\u0644\u062a \u062a\u06a9\u200c\u0635\u0641\u062d\u0647 \u0627\u0633\u062a."},
