gcZ6(){return"\u0628\u0627 \u0627\u06cc\u0646 \u0646\u06a9\u0627\u062a \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u062f\u0631 \u0644\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u0628\u0632\u0631\u06af \u0631\u0627\u062d\u062a\u200c\u062a\u0631 \u062c\u0633\u062a\u200c\u0648\u062c\u0648\u060c \u0641\u06cc\u0644\u062a\u0631\u060c \u0645\u0631\u062a\u0628\u200c\u0633\u0627\u0632\u06cc\u060c \u062e\u0631\u0648\u062c\u06cc \u0628\u06af\u06cc\u0631\u06cc\u062f \u0648 \u0628\u06cc\u0646 \u0633\u062a\u0648\u0646\u200c\u0647\u0627 \u062c\u0627\u0628\u0647\u200c\u062c\u0627 \u0634\u0648\u06cc\u062f."},
