gdx2(){return"\u062f\u0627\u0634\u0628\u0648\u0631\u062f \u067e\u0631\u0648\u0641\u0627\u06cc\u0644"},
dwT(a){return"\u062e\u0637\u0627 \u062f\u0631 \u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u062f\u0627\u0634\u0628\u0648\u0631\u062f \u067e\u0631\u0648\u0641\u0627\u06cc\u0644:\n"+a},
