gdx6(){return"\u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u0647\u0627\u06cc \u0634\u0645\u0627"},
gdwI(){return"\u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627"},
gdx_(){return"\u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f"},
