gd7l(){return"\u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0645\u0648\u062c\u0648\u062f \u0627\u0632 \u062d\u0633\u0627\u0628\u06cc\u06a9\u0633 \u067e\u0631 \u0634\u062f\u0647 \u0627\u0633\u062a. \u0645\u0648\u0627\u0631\u062f \u062e\u0627\u0644\u06cc \u0631\u0627 \u062a\u06a9\u0645\u06cc\u0644 \u06a9\u0646\u06cc\u062f\u061b \u0646\u0627\u0645 \u0648 \u0634\u0645\u0627\u0631\u0647 \u0647\u0645\u0631\u0627\u0647 \u0631\u0627 \u067e\u06cc\u0634 \u0627\u0632 \u062b\u0628\u062a \u0628\u0631\u0631\u0633\u06cc \u06a9\u0646\u06cc\u062f."},
