gbUd(){return"\u0627\u0639\u062a\u0628\u0627\u0631\u0646\u0627\u0645\u0647 \u0628\u0631\u0648\u06a9\u0631 \u0647\u0646\u0648\u0632 \u0630\u062e\u06cc\u0631\u0647 \u0646\u0634\u062f\u0647 \u0627\u0633\u062a."},
