gdHn(){return"\u062a\u0639\u062f\u0627\u062f \u0628\u0631\u0648\u06a9\u0631\u0647\u0627"},
gdHi(){return"\u0628\u0631\u0648\u06a9\u0631\u0647\u0627\u06cc \u0641\u0639\u0627\u0644"},
